     1	# money.ts spec
     2	
     3	All amounts are integer cents.
     4	
     5	## formatCents(cents: number): string
     6	Dollars, a dot, and always two digits of cents. Negative amounts put the minus sign before the dollar sign.
     7	
     8	| call | result |
     9	|---|---|
    10	| formatCents(0) | `$0.00` |
    11	| formatCents(105) | `$1.05` |
    12	| formatCents(123456) | `$1234.56` |
    13	| formatCents(-250) | `-$2.50` |
    14	
    15	## formatReceipt(lines: Array<{ label: string; cents: number }>): string
    16	One line per item, `<label>: <formatCents(cents)>`, then a last line `Total: <formatCents(sum)>`.
    17	Lines are joined with `\n` (no trailing newline). An empty list gives just `Total: $0.00`.
    18	
    19	Example: formatReceipt([{ label: 'Tea', cents: 350 }, { label: 'Refund', cents: -100 }])
    20	returns `Tea: $3.50\nRefund: -$1.00\nTotal: $2.50`.
----
     1	/** Renders integer cents as dollars (see SPEC.md). */
     2	export function formatCents(cents: number): string {
     3		const sign = cents < 0 ? '-' : '';
     4		const abs = Math.abs(cents);
     5		const dollars = Math.floor(abs / 100);
     6		const rest = abs % 100;
     7		return sign + '$' + dollars + '.' + (rest < 10 ? '0' : '') + rest;
     8	}
     9	
    10	/** Renders one line per item plus a total line, joined with newlines (see SPEC.md). */
    11	export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
    12		const total = lines.reduce((sum, line) => sum + line.cents, 0);
    13		const rows = lines.map((line) => line.label + ': ' + formatCents(line.cents));
    14		rows.push('Total: ' + formatCents(total));
    15		return rows.join('\n');
    16	}

